import { createFileSystem } from "../platform/compat/fs.js";
import { DEFAULT_MAX_FILE_SIZE_BYTES } from "../utils/constants/buffers.js";
import { discoverPageFiles } from "./chunk-optimizer/file-discovery.js";
import { snapshotChunkOptimizerFileSystem } from "./chunk-optimizer/filesystem.js";
import { MAX_TOTAL_SOURCE_BYTES } from "./chunk-optimizer/limits.js";
import { analyzePageImports, utf8ByteLength } from "./chunk-optimizer/source-imports.js";
import { generateChunkSuggestions } from "./chunk-optimizer/suggestions.js";
export { generateChunkManifest } from "./chunk-optimizer/manifest.js";
/**
 * Analyze authored Markdown and MDX pages and recommend reusable vendor chunks.
 *
 * Results are deterministic for a stable filesystem snapshot. Operational
 * errors reject instead of returning a partial dependency graph.
 */
export async function analyzeProjectChunks(projectDir, fs) {
    const fileSystem = snapshotChunkOptimizerFileSystem(fs ?? createFileSystem());
    const discoveredPaths = await discoverPageFiles(projectDir, fileSystem);
    const pages = new Map();
    const sharedDeps = new Map();
    let totalSourceBytes = 0;
    for (const path of discoveredPaths) {
        const content = await fileSystem.readTextFile(path);
        if (typeof content !== "string") {
            throw new TypeError(`Chunk analysis filesystem returned non-text content for ${path}`);
        }
        const sourceBytes = utf8ByteLength(content);
        if (sourceBytes > DEFAULT_MAX_FILE_SIZE_BYTES) {
            throw new RangeError(`Chunk analysis source ${path} exceeds ${DEFAULT_MAX_FILE_SIZE_BYTES} bytes`);
        }
        if (sourceBytes > MAX_TOTAL_SOURCE_BYTES - totalSourceBytes) {
            throw new RangeError(`Chunk analysis total source limit of ${MAX_TOTAL_SOURCE_BYTES} bytes was exceeded`);
        }
        totalSourceBytes += sourceBytes;
        const imports = analyzePageImports(content);
        const pageImports = {
            path,
            local: imports.local,
            remote: imports.remote,
            shared: imports.shared,
        };
        pages.set(path, pageImports);
        for (const dependency of new Set([
            ...pageImports.remote,
            ...pageImports.shared,
        ])) {
            sharedDeps.set(dependency, (sharedDeps.get(dependency) ?? 0) + 1);
        }
    }
    return {
        pages,
        sharedDeps,
        suggestedChunks: generateChunkSuggestions(pages, sharedDeps),
    };
}
